var events = $input.all().map(function(item) { return item.json; });
var now = new Date();

var realEvents = events.filter(function(e) {
  if (!e.start || !e.start.dateTime) return false;
  if (e.status === 'cancelled') return false;
  var attendees = e.attendees || [];
  var others = attendees.filter(function(a) {
    return a.email !== 'nelson.torres@adquadrant.com' && !a.self;
  });
  if (attendees.length > 0 && others.length === 0) return false;
  return true;
});

realEvents.sort(function(a, b) {
  return new Date(a.start.dateTime) - new Date(b.start.dateTime);
});

var lines = [];
lines.push('*Calendar Today (' + now.toISOString().split('T')[0] + ')*');
lines.push('');

if (realEvents.length === 0) {
  lines.push('No meetings today. Deep work day.');
} else {
  realEvents.forEach(function(e) {
    var start = new Date(e.start.dateTime);
    var end = new Date(e.end.dateTime);
    var startStr = start.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
    var endStr = end.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
    var duration = Math.round((end - start) / (1000 * 60));

    var attendees = (e.attendees || []).filter(function(a) {
      return a.email !== 'nelson.torres@adquadrant.com' && !a.self;
    });
    var attendeeStr = attendees.map(function(a) {
      return a.displayName || a.email.split('@')[0];
    }).join(', ');

    var joinLink = e.hangoutLink || (e.conferenceData && e.conferenceData.entryPoints && e.conferenceData.entryPoints[0] ? e.conferenceData.entryPoints[0].uri : '');

    var minutesUntil = Math.round((start - now) / (1000 * 60));
    var timeTag = '';
    if (minutesUntil > 0 && minutesUntil <= 30) timeTag = ' (starting soon)';
    else if (minutesUntil <= 0 && minutesUntil > -duration) timeTag = ' (in progress)';

    lines.push('• *' + startStr + ' – ' + endStr + '* (' + duration + 'min)' + timeTag);
    lines.push('  ' + e.summary);
    if (attendeeStr) lines.push('  With: ' + attendeeStr);
    if (joinLink) lines.push('  Join: ' + joinLink);
    lines.push('');
  });

  var totalMeetingMin = realEvents.reduce(function(sum, e) {
    return sum + Math.round((new Date(e.end.dateTime) - new Date(e.start.dateTime)) / (1000 * 60));
  }, 0);
  lines.push('_' + realEvents.length + ' meetings, ' + Math.round(totalMeetingMin / 60 * 10) / 10 + 'h total_');
}

return [{ json: {
  calendar_section: lines.join('\n'),
  event_count: realEvents.length,
  events: realEvents.map(function(e) {
    return {
      id: e.id,
      summary: e.summary,
      start: e.start.dateTime,
      end: e.end.dateTime,
      attendees: (e.attendees || []).map(function(a) { return a.email; })
    };
  })
}}];

